"描述定制嗓音:免选音色——角色配音按项目声纹卡(voice.json 声学字段)自动拼装声线描述,旁白按项目旁白声线卡冻结描述(无卡按工单 --instructions);项目已有冻结 voiceprint 样本时自动作参考锚,同一角色逐句/逐段合成不漂音色。": "Voz personalizada por descripción: sin elegir voz — el doblaje de personajes arma automáticamente la descripción de voz desde la tarjeta de huella vocal del proyecto (campos acústicos de voice.json); la narración usa la descripción congelada de la tarjeta de voz del narrador (sin tarjeta: --instructions de la orden); si ya existe una muestra voiceprint congelada, se usa automáticamente como ancla de referencia y la voz no deriva en síntesis por frase/segmento.",
