"Agent 高级设置": "Ajustes avanzados de Agent",
"Agent 高级设置:扇出型 Agent 并发额度、运行/无输出超时、跨轮对话记忆额度、自动重跑次数上限、重跑等待确认时间、思考深度": "Ajustes avanzados de agentes: concurrencia de agentes fan-out, tiempos de espera de ejecución / sin salida, cuota de memoria conversacional entre turnos, tope de reintentos automáticos, tiempo de espera de confirmación de reintento, profundidad de razonamiento",
"重跑等待确认(秒)": "Espera de confirmación de reintento (s)",
"重跑等待确认需为 {min}-{max} 的整数(秒)": "La espera de confirmación de reintento debe ser un entero entre {min} y {max} (segundos)",
"重跑类确认弹窗(「是否重跑?」等)的等待时长,默认 60 秒:倒计时结束无人答复即自动采用默认选项(通常为「重跑」),流水线不会因等人而卡住。调大可给自己留更多裁决时间,代价是无人值守时流水线在弹窗上等得更久;Agent 显式指定的更短等待仍有效,但不能超过本值。签字类弹窗(H 门人工签字)永不倒计时、永不自动确认,不受本项影响。全局设置,保存后对后续发起的确认生效。": "Tiempo de espera de los avisos de confirmación de reintento («¿Reintentar?», etc.), 60 segundos por defecto: si la cuenta atrás termina sin respuesta se aplica automáticamente la opción por defecto (normalmente «Reintentar»), de modo que la canalización nunca se queda bloqueada esperando a alguien. Auméntalo para darte más tiempo de decisión, a costa de que, sin nadie presente, la canalización espere más en el aviso; una espera más corta indicada explícitamente por un agente sigue siendo válida, pero nunca puede superar este valor. Los avisos de firma (firma manual de puertas H) nunca tienen cuenta atrás ni se confirman solos, por lo que no se ven afectados. Ajuste global; surte efecto para las confirmaciones emitidas tras guardar.",
"⚙️ Agent 高级设置": "⚙️ Ajustes avanzados de Agent",
"重跑次数": "Reintentos",
"Agent 自动重跑/重 roll 的次数上限,默认 0:验收评分、QA 审核或机检不过时,总制片带意见自动退回重做;视频/图像生成机检不达标时自动重 roll。同一任务累计达到该次数仍不过就升级用户裁决,不再自行重试;填 0 则完全不自动重跑,首次不过即升级人工。全局设置,通过运行提示词注入所有 Agent,覆盖流程文档里写死的「最多 3 次」,保存后对后续启动的工单生效。": "Tope de reejecuciones / re-rolls automáticos de los agentes, 0 por defecto: si la puntuación de aceptación, la revisión QA o la comprobación automática fallan, el Productor devuelve el trabajo con comentarios para rehacerlo; si la generación de vídeo/imagen no supera la comprobación automática, se re-rollea automáticamente. Cuando la misma tarea alcanza este número y sigue fallando, se escala al usuario en lugar de reintentar; 0 desactiva por completo el reintento automático (el primer fallo se escala). Ajuste global, inyectado a todos los agentes mediante el prompt de ejecución y que sobrescribe el «máximo 3 veces» fijado en la documentación; se aplica a las ejecuciones iniciadas tras guardar.",
"重跑次数需为 0-{max} 的整数(0=不自动重跑)": "El número de reintentos debe ser un entero entre 0 y {max} (0 = sin reintento automático)",
"轮次上限": "Límite de turnos",
"单个工单内引擎的对话轮次上限,默认 250:仅对 claude 与 grok 引擎生效(headless 的 --max-turns 参数,不传则不限,这里主动设闸防失控循环);codex/pi/opencode 引擎无此参数不受影响,deepagents 走框架自身的递归上限。撞上限时引擎会被直接切断且无法续跑,回执只显示退出码 1,已落盘的产物保留但核验与回执缺失——大批量工位(逐组选片、批量切片)一单几十组时 100 轮远远不够,如仍撞限优先调小派单批宽、其次上调本值。全局设置,保存后对后续启动的工单生效。": "Tope de turnos de conversación del motor por orden de trabajo, por defecto 250: solo afecta a los motores claude y grok (el parámetro headless --max-turns; omitirlo significa sin límite — esta compuerta evita bucles descontrolados). Los motores codex/pi/opencode no tienen este parámetro y no se ven afectados; deepagents usa el límite de recursión de su propio framework. Al alcanzar el tope, el motor se corta sin posibilidad de reanudar — el recibo solo muestra código de salida 1; los artefactos ya guardados se conservan, pero faltan la verificación y el recibo. En estaciones de gran volumen (selección por grupo, corte por lotes) una orden con decenas de grupos hace que 100 turnos sean muy pocos; si aún se alcanza el tope, primero reduzca el tamaño del lote y luego suba este valor. Ajuste global; se aplica a las ejecuciones iniciadas tras guardar.",
"轮次上限需为 {min}-{max} 的整数": "El límite de turnos debe ser un entero entre {min} y {max}",
"思考深度": "Profundidad de razonamiento",
"引擎默认": "Predeterminado del motor",
"思考深度(Thinking Effort)统一设置,默认「引擎默认」:派单时按当前引擎翻译成各自的推理强度参数——claude → --effort,codex → model_reasoning_effort(无 max,按 xhigh),pi → --thinking,opencode → --variant(模型没有该档位时被忽略),grok → --reasoning-effort(无 max,按 xhigh),deepagents → reasoning_effort(仅云端/OpenRouter 渠道,本地模型不传);kimi CLI 无对应参数,不受影响。越深越稳但越慢、token 消耗越高;「引擎默认」不传任何参数,沿用各引擎自身配置(如 ~/.claude/settings.json 的 effortLevel、~/.codex/config.toml 的 model_reasoning_effort)。全局设置,对所有 Agent 生效,保存后对后续启动的工单生效。": "Ajuste unificado de profundidad de razonamiento (Thinking Effort), predeterminado «Predeterminado del motor»: al despachar se traduce al parámetro de intensidad de razonamiento de cada motor — claude → --effort, codex → model_reasoning_effort (sin max; se usa xhigh), pi → --thinking, opencode → --variant (se ignora si el modelo no tiene ese nivel), grok → --reasoning-effort (sin max; se asigna a xhigh), deepagents → reasoning_effort (solo canales nube/OpenRouter; no se envía a modelos locales); la CLI de kimi no tiene parámetro equivalente y no se ve afectada. Más profundidad es más estable pero más lenta y consume más tokens; «Predeterminado del motor» no pasa nada y conserva la configuración propia de cada motor (p. ej. effortLevel en ~/.claude/settings.json, model_reasoning_effort en ~/.codex/config.toml). Ajuste global para todos los agentes, efectivo en las ejecuciones iniciadas tras guardar.",
