"最大参考图数量需为 0-30 的整数": "El máximo de imágenes de referencia debe ser un entero entre 0 y 30",
"最大参考视频数量需为 0-10 的整数": "El máximo de vídeos de referencia debe ser un entero entre 0 y 10",
"最大参考音频数量需为 0-10 的整数": "El máximo de audios de referencia debe ser un entero entre 0 y 10",
"参考图已满({m} 张),不能再添加": "Referencias completas ({m} imágenes); no se pueden añadir más",
"Seedance 2.5(最新,单段30秒直出,参考上限30图+10视频+10音频,480p/720p)": "Seedance 2.5 (el más reciente, vídeo de 30 segundos en una sola generación, hasta 30 imágenes + 10 vídeos + 10 audios de referencia, 480p/720p)",
"Seedance 2.0(音画同生,多模态生视频,最高4K)": "Seedance 2.0 (audio y vídeo simultáneos, vídeo multimodal, hasta 4K)",
"对话记忆": "Memoria conversacional",
"对话记忆额度(KB,默认 16):创作型 Agent 每次运行接续上次会话,多轮对话有连续记忆;单个会话历史超过该额度自动新开会话防膨胀(扇出型无状态 Agent 本就每单全新会话,不受此项影响)。调大可保留更长的连续记忆,但 resume 每轮重发全部历史,越大越慢、token 消耗越高。拖到 0 即完全关闭:所有 Agent(含总制片)每次运行/发言都是全新会话,跨工单信息只靠落盘产物(bible、工单档案等)传递,可显著省 token,但对话上下文不再延续。全局设置,保存后立即对后续运行生效;调小或关闭期间会话号照常回存,重新调大后从最近一次会话继续。": "Cuota de memoria conversacional (KB, por defecto 16): los Agents creativos reanudan su sesión anterior en cada ejecución, de modo que las conversaciones multivuelta mantienen memoria continua; si el historial de una sesión supera esta cuota, se abre automáticamente una sesión nueva para evitar el crecimiento excesivo (los Agents fan-out sin estado ya inician una sesión nueva por ticket y no se ven afectados). Una cuota mayor conserva memoria continua más larga, pero resume reenvía todo el historial en cada turno: cuanto mayor, más lento y más tokens consume. Arrástrala a 0 para desactivarla por completo: todos los Agents — incluido el Productor — inician una sesión nueva en cada ejecución/mensaje, y la información entre tickets solo viaja por los artefactos en disco (bible, expedientes de tickets, etc.), lo que ahorra muchos tokens pero pierde la continuidad conversacional. Ajuste global; surte efecto de inmediato en las ejecuciones posteriores. Mientras esté reducida o en 0, los ID de sesión se siguen guardando: al volver a subirla se reanuda desde la sesión más reciente.",
"✓ 会话恢复生效中:单会话超过 {kb} KB 自动新开": "✓ Reanudación de sesión activa: una sesión que supere {kb} KB se reinicia automáticamente",
"对话记忆需为 0-{max} 的整数(KB,0=关闭)": "La memoria conversacional debe ser un entero entre 0 y {max} (KB, 0 = desactivada)",
"已关闭:每次运行全新会话": "Desactivada: cada ejecución inicia sesión nueva",
"跨 Agent 并发额度": "Cupo de concurrencia entre Agents",
"全局同时运行的工单(工人进程)总上限,默认 8,最高 50:所有 Agent 的运行共用这一池进程槽,占满后新工单排队等槽;总制片等调度型 Agent 大部分时间静默等子任务,不占槽。它同时是下方「单 Agent 并发额度」的取值上限。每个槽 = 一个真实的模型 CLI 进程,调大会同步放大 token 消耗速度、本机负载与网络代理并发压力,建议按机器与额度承受力逐步上调。保存后立即对后续启动的工单生效。": "Tope global de tickets (procesos de trabajo) en ejecución simultánea; por defecto 8, máximo 50. Las ejecuciones de todos los Agents comparten este único grupo de ranuras de proceso; al llenarse, los nuevos tickets esperan una ranura. Los Agents coordinadores, como el productor general, pasan la mayor parte del tiempo esperando subtareas y no ocupan ranura. También es el límite superior del «Cupo de concurrencia por Agent» de abajo. Cada ranura = un proceso CLI real del modelo: subir el valor amplifica a la vez el ritmo de consumo de tokens, la carga local y la presión de concurrencia sobre el proxy, así que auméntalo gradualmente según lo que soporten tu máquina y tu cuota. Se aplica a las ejecuciones iniciadas tras guardar.",
"跨 Agent 并发额度需为 1-{max} 的整数": "El cupo de concurrencia entre Agents debe ser un entero entre 1 y {max}",
"单 Agent 并发额度": "Cupo de concurrencia por Agent",
"扇出型 Agent(场景资产、视频生成、审核、验收评分等按场景/组一单的工位)同一 Agent 可同时运行的工单数上限,默认 5,最大不超过上方「跨 Agent 并发额度」。创作型 Agent 为保护会话连续性恒为串行,不受此值影响;全部运行仍受跨 Agent 并发额度总闸。每个并发 = 一个真实的模型 CLI 进程,调大会成倍加快额度消耗,网络代理高并发下也更易断连,建议逐步上调。": "Límite de tickets que un mismo Agent de tipo fan-out (puestos que procesan un ticket por escena/grupo, como activos de escena, generación de vídeo, revisión y puntuación de aceptación) puede ejecutar simultáneamente; por defecto 5, nunca por encima del «Cupo de concurrencia entre Agents» de arriba. Los Agents creativos siempre se ejecutan en serie para proteger la continuidad de la sesión y no se ven afectados; todas las ejecuciones siguen pasando por la compuerta de concurrencia entre Agents. Cada concurrencia = un proceso CLI real del modelo: subir el valor acelera proporcionalmente el consumo de cuota y facilita cortes del proxy con alta concurrencia, así que auméntalo gradualmente.",
"运行超时(分钟)": "Tiempo límite de ejecución (min)",
"无输出超时(分钟)": "Tiempo límite sin salida (min)",
"运行超时:单个工单从启动算起的墙钟上限,默认 120 分钟(总制片要等整条流水线,自动放宽 4 倍),到点连同派生子进程一起终止并记为出错,是回收挂死进程的最后防线。无输出超时:引擎连续多长时间没有任何事件输出即判定挂死并终止,默认 30 分钟,填 0 关闭;比墙钟更早识别 API 长连接不返回、代理断流等假死,又不会误伤跑得慢但在正常干活的长批量任务(总制片大部分时间静默等子任务,不受此项约束)。注意单次工具调用期间引擎不会有事件输出,该值须大于工单里最长的一次工具调用。均为全局设置,保存后对后续启动的工单生效。": "Tiempo límite de ejecución: tope de reloj de pared de un ticket desde su inicio, 120 minutos por defecto (el Productor espera toda la línea y recibe automáticamente 4×); al cumplirse se termina la ejecución con sus procesos hijos y se marca como error: la última defensa para recuperar procesos colgados. Tiempo límite sin salida: cuánto puede pasar el motor sin emitir ningún evento antes de darse por colgado y terminarse, 30 minutos por defecto, 0 lo desactiva; detecta bloqueos (conexiones API que nunca vuelven, cortes de proxy) mucho antes que el reloj de pared sin perjudicar trabajos por lotes lentos pero sanos (el Productor pasa la mayor parte del tiempo esperando subtareas en silencio y está exento). Ojo: durante una llamada de herramienta el motor no emite eventos, así que este valor debe superar la llamada más larga del ticket. Ambos son ajustes globales y aplican a las ejecuciones iniciadas tras guardar.",
"运行超时需为 {min}-{max} 的整数(分钟)": "El tiempo límite de ejecución debe ser un entero entre {min} y {max} (minutos)",
"无输出超时需为 0-{max} 的整数(分钟,0=关闭)": "El tiempo límite sin salida debe ser un entero entre 0 y {max} (minutos, 0 = desactivado)",
"并发额度需为 1-{max} 的整数": "El cupo de concurrencia debe ser un entero entre 1 y {max}",
