"构想、风格与叙事节奏保存在项目的 brief.md,注入该项目每个 Agent 的系统提示词,作为最高创作前提;画面风格约束全部画面视觉产出,叙事节奏的节拍链约束剧本分集/分场与分镜节拍。保存后对之后派发的任务生效;全部清空保存则移除该设定": "El concepto, el estilo y el ritmo narrativo se guardan en el brief.md del proyecto y se inyectan en el prompt de sistema de cada agente como premisa creativa máxima; el estilo visual rige toda la salida visual y la cadena de beats del ritmo rige la división en episodios/escenas del guion y los beats del storyboard. Se aplica a las tareas asignadas tras guardar; guarda con todo vacío para eliminar el ajuste",
