",自动运行每次唤醒总制片时都随消息附带,总制片会话重开也不丢失;适合放长期约束,建议写成条件式(如「在 ep01-ep10 剧本全部完成前,不派设定类工单」),留空则不附带": ", se adjuntan al mensaje cada vez que la ejecución automática despierta al Productor, por lo que no se pierden aunque se reabra la sesión; ideales para restricciones a largo plazo, preferiblemente en forma condicional (p. ej. 「hasta completar todos los guiones de ep01-ep10, no asignar órdenes de trabajo de tipo diseño」); si se deja vacío no se adjunta nada",
"在 ep01-ep10 剧本全部完成前,不派设定类工单": "Hasta completar todos los guiones de ep01-ep10, no asignar órdenes de trabajo de tipo diseño",
"常任指令不能超过 2000 字": "Las órdenes permanentes no pueden superar los 2000 caracteres",
"闲置时间(min)": "Tiempo de inactividad (min)",
"闲置时间:每隔该时长巡检一次,流水线空闲(无任务在跑、无待确认项)才发送状态检查消息,默认 5 分钟。阈值:总制片生效引擎(claude/codex)的 5 小时窗口会话用量达到该值时,本轮不发送;用量读取不到时放行。均为全局设置,对所有项目生效(开关在运行面板 🤖 按钮,按项目独立)": "Tiempo de inactividad: se comprueba una vez por cada intervalo de esa duración y solo se envía el mensaje de comprobación de estado si la pipeline está inactiva (sin tareas en ejecución ni elementos por confirmar); por defecto 5 minutos. Umbral: si el uso de sesión de la ventana de 5 horas del motor activo del Productor (claude/codex) alcanza ese valor, no se envía en esa ronda; si el uso no puede leerse, se deja pasar. Ambos son ajustes globales que se aplican a todos los proyectos (el interruptor está en el botón 🤖 del panel de ejecución, independiente por proyecto)",
"闲置时间需为 1-720 的整数(分钟)": "El tiempo de inactividad debe ser un entero de 1 a 720 (minutos)",
