"开启时在运行结束与生成结束处按字段白名单记录结构化事件(引擎/Agent/渠道/状态/时长/脱敏后的错误模板),只写入本机 data/.videoagents/telemetry/,不含提示词、项目内容、文件路径与 API Key,永不自动上传。「导出诊断包」生成一个 zip(事件 + 环境摘要 + 下方勾选的经验卡),由你自行提交给开发者(如 GitHub issue 附件),用于改进产品。": "Al activarlo, se registran eventos estructurados al finalizar ejecuciones y generaciones según una lista blanca de campos (motor/Agent/canal/estado/duración/plantilla de error anonimizada), escritos solo en data/.videoagents/telemetry/ de esta máquina — sin prompts, contenido del proyecto, rutas de archivos ni API Keys, y nunca se suben automáticamente. \"Exportar paquete de diagnóstico\" genera un zip (eventos + resumen del entorno + las tarjetas de experiencia marcadas abajo) que tú mismo envías a los desarrolladores (p. ej. como adjunto en un issue de GitHub) para mejorar el producto.",
