"点击「启用」后,可在下方管理已入库的素材;人物预览页每张形象图会出现「入库」按钮,分镜重出时已入库(Active)的参考图自动以资产 URI(asset://素材ID)提交。": "Tras pulsar «Activar», gestione abajo los activos registrados; cada imagen en la vista previa de personajes tendrá un botón «Registrar», y al regenerar un grupo las referencias registradas (Active) se envían automáticamente como URI de activo (asset://ID).",
"注意:上传入库为异步审核(Processing → Active/Failed),仅 Active 状态的素材可用于视频生成;素材按方舟「项目」隔离,下方 ProjectName 须与「生成模型」页视频生成所用方舟 API Key 所属项目一致(默认 default)。": "Nota: el registro se revisa de forma asíncrona (Processing → Active/Failed); solo los activos Active sirven para generar vídeo. Los activos se aíslan por proyecto de Ark: el ProjectName de abajo debe coincidir con el proyecto de la API Key de Ark usada en la página de modelos de generación (por defecto, default).",
