"视频提示词技能:Prompt 工程师写组级视频提示词时必须套用的官方提示词技能。自动=按真正跑视频生成的模型解析(Seedance 2.5→sd25-pe,Seedance 2.0 系列→sd20-prompt-writing,MiniMax H3→h3-prompt-writing);解析不到时可手选或跳过。H3A 分镜签字时会再次确认并冻结": "Skill de prompt de vídeo: el skill oficial de redacción de prompts que el ingeniero de prompts debe aplicar al escribir los prompts de vídeo por grupo. Auto = resuelto según el modelo que realmente ejecuta la generación de vídeo (Seedance 2.5→sd25-pe, familia Seedance 2.0→sd20-prompt-writing, MiniMax H3→h3-prompt-writing); si no hay coincidencia, elegir manualmente u omitir. Se reconfirma y congela en la firma H3A del storyboard",
