"长镜头": "Plano secuencia",
"开启后每个分镜组把上一组的尾帧截图作为参考图续接画面;关闭(默认)则不挂尾帧参考图,仅靠文字承接上一组结尾(换构图开场句)": "Al activarlo, cada grupo de planos adjunta la captura del último fotograma del grupo anterior como imagen de referencia para dar continuidad; desactivado (por defecto) no se adjunta esa referencia y la continuidad se apoya solo en el texto (frase de apertura con reencuadre)",
"⚠ 当前草稿分辨率较低,不建议开启长镜头:低清尾帧作参考图会导致画面质量与人物一致性明显下降": "⚠ La resolución de borrador actual es baja; no se recomienda activar el plano secuencia: usar un último fotograma de baja resolución como referencia degradará notablemente la calidad de imagen y la consistencia de los personajes",
"Seedance 2.5(Fal 托管;单段 4-30 秒,参考 30 图/10 视频/10 音频,480p/720p/1080p)": "Seedance 2.5 (alojado en Fal; clip único de 4–30 s, referencias 30 imágenes/10 vídeos/10 audios, 480p/720p/1080p)",
"Seedance 2.0(Fal 托管;音画同生,4-15 秒,参考 9 图/3 视频/3 音频,最高 4K)": "Seedance 2.0 (alojado en Fal; generación conjunta de audio y vídeo, 4–15 s, referencias 9 imágenes/3 vídeos/3 audios, hasta 4K)",
"Wan 3.0(Fal 托管;文生/首尾帧/多模态参考,2-30 秒,参考 10 图/5 视频/5 音频(视频、音频各合计 ≤15s),480p/720p/1080p)": "Wan 3.0 (alojado en Fal; texto / primer-último fotograma / referencias multimodales, 2–30 s, referencias 10 imágenes/5 vídeos/5 audios (vídeos y audios ≤15 s en total cada uno), 480p/720p/1080p)",
"MiniMax H3(Fal 托管;首尾帧/多模态参考,480P/768P/2K/4K,参考合计 ≤12 件)": "MiniMax H3 (alojado en Fal; primer/último fotograma o referencias multimodales, 480P/768P/2K/4K, ≤12 archivos de referencia en total)",
"Seedream 5.0 Lite(Fal 托管;文/图生图/多参考图 ≤10,出图 2K–4K)": "Seedream 5.0 Lite (alojado en Fal; texto/imagen a imagen, hasta 10 imágenes de referencia, salida 2K–4K)",
"Seedream 4.5(Fal 托管;文/图生图/多图融合,参考图 ≤10)": "Seedream 4.5 (alojado en Fal; texto/imagen a imagen, fusión multiimagen, hasta 10 imágenes de referencia)",
"Nano Banana Pro(Fal 托管;Google 生成/编辑旗舰版,多参考图,1K/2K/4K)": "Nano Banana Pro (alojado en Fal; modelo insignia de Google para generación/edición, varias referencias, 1K/2K/4K)",
"Nano Banana 2(Fal 托管;Google 快速版生成/编辑,多参考图)": "Nano Banana 2 (alojado en Fal; modelo rápido de Google para generación/edición, varias referencias)",
"GPT Image 2.5 Flare(Fal 托管;OpenAI 通用版,参考图 ≤16,无 seed)": "GPT Image 2.5 Flare (alojado en Fal; OpenAI de uso general, hasta 16 imágenes de referencia, sin seed)",
"GPT Image 2(Fal 托管;OpenAI,参考图 ≤16,无 seed)": "GPT Image 2 (alojado en Fal; OpenAI, hasta 16 imágenes de referencia, sin seed)",
"FLUX.2 Pro(Fal 托管;文生图/多图编辑)": "FLUX.2 Pro (alojado en Fal; texto a imagen / edición multiimagen)",
"FLUX.2 Max(Fal 托管;旗舰版,文生图/多图编辑)": "FLUX.2 Max (alojado en Fal; insignia, texto a imagen / edición multiimagen)",
"FLUX Kontext Max(Fal 托管;文生图/多参考图编辑)": "FLUX Kontext Max (alojado en Fal; texto a imagen / edición con varias referencias)",
"Qwen Image 3(Fal 托管;中英提示词,参考图 ≤3,支持负面提示词)": "Qwen Image 3 (alojado en Fal; prompts en chino/inglés, hasta 3 imágenes de referencia, admite prompt negativo)",
"HunyuanImage 3.0(Fal 托管;仅文生图,支持负面提示词)": "HunyuanImage 3.0 (alojado en Fal; solo texto a imagen, admite prompt negativo)",
"Fal 图像生成 API(queue.fal.run 异步队列,托管 Seedream、Nano Banana、GPT Image、FLUX.2、Qwen Image 等端点);模型 ID 填家族前缀,无参考图走文生图端点、有参考图自动切 edit 端点,「自定义…」也可填完整端点 ID;尺寸/参考图上限/seed 按模型映射;Key 与视频段 Fal 共用(任一处填写即可),在": "API de generación de imágenes de Fal (cola asíncrona queue.fal.run que aloja Seedream, Nano Banana, GPT Image, FLUX.2, Qwen Image y más); el ID de modelo es el prefijo de familia: sin referencias se usa el endpoint texto a imagen y con referencias se cambia automáticamente al endpoint de edición; «Personalizado…» también admite un ID de endpoint completo; tamaño / límite de referencias / seed se mapean por modelo; la clave se comparte con la pestaña Vídeo → Fal (basta con rellenar una) y se crea en",
"MiniMax H3 Max(Fal 托管;H3 后训练版,提示遵循更强)": "MiniMax H3 Max (alojado en Fal; H3 post-entrenado, mayor fidelidad al prompt)",
"MiniMax H3 Max Turbo(Fal 托管;速度优先版,仅文生/首尾帧,480P/768P,不支持参考素材)": "MiniMax H3 Max Turbo (alojado en Fal; variante rápida, solo texto/primer-último fotograma, 480P/768P, sin material de referencia)",
"Kling 3.0 Pro(Fal 托管;首尾帧,3-15 秒,原生音频,不支持参考素材)": "Kling 3.0 Pro (alojado en Fal; primer/último fotograma, 3–15 s, audio nativo, sin material de referencia)",
"Kling 3.0 Standard(Fal 托管;首尾帧,3-15 秒,原生音频,不支持参考素材)": "Kling 3.0 Standard (alojado en Fal; primer/último fotograma, 3–15 s, audio nativo, sin material de referencia)",
"Fal 视频生成 API(queue.fal.run 异步队列,托管 Seedance 2.0/2.5、MiniMax H3、Kling 3.0、Wan 3.0 等端点);模型 ID 填家族前缀,按输入自动补 text-to-video / image-to-video / reference-to-video 任务段,「自定义…」也可填完整端点 ID;分辨率/时长/参考素材上限随所选模型(与官方渠道同口径);Key 在": "API de generación de vídeo de Fal (cola asíncrona queue.fal.run que aloja Seedance 2.0/2.5, MiniMax H3, Kling 3.0, Wan 3.0 y más); el ID de modelo es el prefijo de familia y el segmento de tarea text-to-video / image-to-video / reference-to-video se añade automáticamente según las entradas, o elige “Personalizado…” para introducir un ID de endpoint completo; los límites de resolución/duración/referencias siguen el modelo elegido (mismas reglas que los canales oficiales); crea la Key en el",
"fal.ai 控制台「API Keys」": "panel de fal.ai “API Keys”",
"直播": "En directo",
"直播:参考图 + 提示词交给 Fal 渠道视频模型循环生成 480p 短段,每段带上一段尾帧续接,页面把新段接在已播内容之后连续播放": "En directo: las imágenes de referencia y el prompt se envían a un modelo de vídeo de Fal que genera clips de 480p sin parar, cada uno continuando desde el último fotograma del anterior; la página añade los clips nuevos tras lo ya reproducido para una reproducción continua",
"直播 — Agentics:VideoAgents": "En directo — Agentics:VideoAgents",
"📡 直播": "📡 En directo",
"参考图 + 提示词 → Fal 视频模型循环生成 480p 短段 → 尾帧续接 → 连续播放": "Referencias + prompt → el modelo de vídeo Fal genera clips 480p en bucle → continuación por último fotograma → reproducción continua",
"🗑 清理历史片段": "🗑 Limpiar clips antiguos",
"删除所有已停止会话的片段视频与尾帧,释放磁盘": "Elimina los clips y últimos fotogramas de todas las sesiones detenidas para liberar disco",
