"人物/场景/风格锚图;每一轮都会连同上一段的尾帧一起作为参考提交,保持人物一致。启动后冻结,停止后可改。": "Imágenes ancla de personajes/escena/estilo; en cada ronda se envían como referencia junto con el último fotograma del clip anterior para mantener la coherencia. Se bloquean al iniciar; editables tras detener.",
