"例如:一位年轻主播坐在暖光直播间里,面对镜头微笑聊天,偶尔喝一口咖啡,背景霓虹灯牌缓慢闪烁": "p. ej. Un joven streamer sentado en un estudio de luz cálida, sonriendo y charlando a cámara, bebiendo café de vez en cuando, con un letrero de neón parpadeando lentamente al fondo",
