"播放策略:按顺序播放已生成的片段;新片段还没到时重播最新一段,到了就在当前段结束后接上,不会打断正在播的画面。生成通常慢于播放,所以\"回放\"是常态——把单段时长调长可以减少重播占比。待播片段达到上限(默认 3 段,高级选项可调)时暂停生成,播掉一段再继续。停止后循环回放全部片段。": "Reproducción: los clips generados se reproducen en orden; mientras no llega el siguiente se repite el último y el nuevo se añade al terminar el actual sin interrumpirlo. Generar suele ser más lento que reproducir, así que repetir es normal; clips más largos reducen la proporción de repetición. Al alcanzar el límite de clips en espera (3 por defecto, ajustable en Opciones avanzadas) la generación se pausa y se reanuda al reproducir uno. Tras detener, todos los clips se reproducen en bucle.",
